input.sparql:
PREFIX brick: <http://brickschema.org/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z rdfs:label ?label .
  FILTER(?label = "Perimeter_bot_ZN_1")
}

PREFIX brick: <http://brickschema.org/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?label WHERE {
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label, "Perimeter_bot"))
}

PREFIX ref: <http://contextualstores.example.org/ref#>
SELECT ?sensor ?tsid WHERE {
  ?sensor ref:hasTimeseriesId ?tsid .
  FILTER(?sensor = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z04.Zone_Air_Temperature_Sensor>
        || ?sensor = <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z04.Zone_Air_Cooling_Temperature_Setpoint>)
}
